style.css:
@-moz-document domain("web.whatsapp.com") {
/* 1. FONDO DE MALLA (Indispensable) */
    html, body {
        background-color: #030712 !important;
        background-image: 
            radial-gradient(at 10% 20%, rgba(56, 189, 248, 0.2) 0px, transparent 50%),
            radial-gradient(at 90% 10%, rgba(168, 85, 247, 0.2) 0px, transparent 50%),
            radial-gradient(at 50% 50%, rgba(30, 58, 138, 0.15) 0px, transparent 80%) !important;
        background-attachment: fixed !important;
    }

    /* 2. FORZADO DE TRANSPARENCIA TOTAL (Limpia el modo oscuro de WhatsApp) */
    #app, .app-wrapper-web, .two, .three, main, 
    header, #main, #side, [data-testid="conversation-panel-wrapper"],
    [data-testid="conversation-panel-body"], 
    [data-testid="chat-list"], ._1AD9M, ._3bc6H, ._2g_YF {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 3. ELIMINAR EL DIBUJO/WALLPAPER (Las ballenas) */
    [data-testid="conversation-panel-body"] > div:first-child[style*="background-image"],
    [style*="background-image"] {
        background-image: none !important;
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 4. BARRA LATERAL (Efecto Cristal Denso) */
    #side, [data-testid="side"] {
        background: rgba(15, 23, 42, 0.4) !important;
        backdrop-filter: blur(40px) saturate(180%) !important;
        -webkit-backdrop-filter: blur(40px) saturate(180%) !important;
        border-right: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    /* 5. CABECERAS (Header del Chat y Sidebar) */
    header, [data-testid="chat-header"] {
        background: rgba(15, 23, 42, 0.5) !important;
        backdrop-filter: blur(20px) !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.05) !important;
    }

    /* 6. BURBUJAS DE MENSAJE (Efecto Cristal Líquido) */
    /* La caja común de todos los mensajes */
    .message-in > div > div, .message-out > div > div, 
    [data-testid="msg-container"] > div {
        backdrop-filter: blur(15px) !important;
        -webkit-backdrop-filter: blur(15px) !important;
        border-radius: 16px !important;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        padding: 5px !important;
    }

    /* Mensajes RECIBIDOS (Cristal Grisáceo) */
    .message-in > div > div {
        background: rgba(255, 255, 255, 0.07) !important;
        color: #f1f5f9 !important;
    }

    /* Mensajes ENVIADOS (Cristal Azulado) */
    .message-out > div > div {
        background: rgba(37, 99, 235, 0.25) !important;
        border-color: rgba(56, 189, 248, 0.3) !important;
        color: #ffffff !important;
    }

    /* 7. BARRA DE ESCRITURA (Footer) */
    footer, [data-testid="composer-footer"] {
        background: rgba(15, 23, 42, 0.7) !important;
        backdrop-filter: blur(30px) !important;
        border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    footer [data-testid="input-placeholder"], 
    footer [contenteditable="true"] {
        background: rgba(255, 255, 255, 0.05) !important;
        border-radius: 20px !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        color: white !important;
    }

    /* 8. LISTA DE CHATS (Texto) */
    [data-testid="chat-list"] [dir="auto"] {
        color: #f8fafc !important;
    }
    
    /* El nombre del contacto en el chat abierto */
    [data-testid="chat-header"] span {
        color: white !important;
    }

    /* 9. BOTÓN DE SCROLL ABAJO */
    [data-testid="btn-scrollbar-bottom"] {
        background: rgba(255, 255, 255, 0.1) !important;
        backdrop-filter: blur(10px) !important;
    }
}
